fn is_happy(s: Vec<char>) -> bool {
    // A happy sequence must have at least 3 characters.
    if s.len() < 3 {
        return false;
    }

    // Check every window of size 3 for pairwise distinct characters.
    s.windows(3).all(|w| {
        w[0] != w[1] &&
        w[0] != w[2] &&
        w[1] != w[2]
    })
}

